def _validate_group_rank_stability_result(
    result: Any, *, where: str = "result"
) -> tuple[str, list[str], list[str], list[dict]]:
    """Validate a complete :func:`group_rank_stability` result.

    Returns the reference group, the remaining groups, the scenario
    axis and the flat ``data`` rows, checking the
    ``climate-grid/ggs-v1`` contract: key order, the schema, the
    reference/groups/scenarios axes, the ranked-then-unranked row
    order and each row's key order ``group, total, valid, coverage,
    mean, std, uncertainty, rank``.  Ranked rows run consecutively
    from 1 and precede the ``rank`` ``None`` rows; the unranked rows
    keep the original group order; every group appears exactly once.
    ``mean``, ``std`` and ``uncertainty`` are finite numbers (``std``
    and ``uncertainty`` non-negative) exactly when ``rank`` is not
    ``None`` and are ``None`` together otherwise.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _GROUP_RANK_STABILITY_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, reference, "
            "groups, scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _GROUP_RANK_STABILITY_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_GROUP_RANK_STABILITY_SCHEMA!r}"
        )

    reference = result["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

    groups = _validate_string_list(result["groups"], f"{where}.groups")
    scenarios = _validate_string_list(
        result["scenarios"], f"{where}.scenarios"
    )
    if reference in groups:
        raise ValueError(
            f"{where}.reference must not appear in {where}.groups"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(groups):
        raise ValueError(
            f"{where}.data must have {len(groups)} rows (one per group, "
            "in ranked-then-unranked order)"
        )

    group_index = {group: index for index, group in enumerate(groups)}
    seen_groups: set[str] = set()
    valid_count = 0
    null_phase = False
    invalid_order = -1
    for row_index, row in enumerate(data):
        row_where = f"{where}.data[{row_index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _GROUP_RANK_STABILITY_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys group, total, "
                "valid, coverage, mean, std, uncertainty, rank in order"
            )

        group = row["group"]
        if not isinstance(group, str):
            raise TypeError(f"{row_where}.group must be a str")
        if group not in group_index:
            raise ValueError(
                f"{row_where}.group {group!r} must appear in {where}.groups"
            )
        if group in seen_groups:
            raise ValueError(
                f"{row_where}: group {group!r} appears more than once"
            )
        seen_groups.add(group)
        order = group_index[group]

        total = row["total"]
        if not isinstance(total, int) or isinstance(total, bool):
            raise TypeError(f"{row_where}.total must be a non-bool int")
        if total != len(scenarios):
            raise ValueError(
                f"{row_where}.total must equal the number of scenarios"
            )

        valid = row["valid"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{row_where}.valid must be a non-bool int")
        if not 0 <= valid <= total:
            raise ValueError(
                f"{row_where}.valid must be between 0 and {row_where}.total"
            )

        _validate_number(
            row["coverage"], f"{row_where}.coverage", nullable=False
        )
        if not 0 <= row["coverage"] <= 1:
            raise ValueError(
                f"{row_where}.coverage must be between 0 and 1"
            )
        if row["coverage"] != round(valid / total, 12):
            raise ValueError(
                f"{row_where}.coverage must equal round(valid / total, 12)"
            )

        mean = row["mean"]
        std = row["std"]
        uncertainty = row["uncertainty"]
        rank = row["rank"]
        if rank is not None and (
            not isinstance(rank, int) or isinstance(rank, bool)
        ):
            raise TypeError(
                f"{row_where}.rank must be a non-bool int or None"
            )
        if rank is None:
            null_phase = True
            if mean is not None or std is not None or uncertainty is not None:
                raise ValueError(
                    f"{row_where}: mean, std and uncertainty must be None "
                    "when rank is None"
                )
            if order <= invalid_order:
                raise ValueError(
                    f"{row_where}: unranked rows must keep the original "
                    "group order"
                )
            invalid_order = order
        else:
            if null_phase:
                raise ValueError(
                    f"{row_where}: ranked rows must precede rows with "
                    "rank None"
                )
            if mean is None or std is None or uncertainty is None:
                raise ValueError(
                    f"{row_where}: mean, std and uncertainty must all be "
                    "present when rank is not None"
                )
            if valid < 1:
                raise ValueError(
                    f"{row_where}.valid must be positive when rank is not "
                    "None"
                )
            valid_count += 1
            if rank != valid_count:
                raise ValueError(
                    f"{row_where}.rank must run consecutively from 1"
                )
            _validate_number(mean, f"{row_where}.mean", nullable=False)
            _validate_number(std, f"{row_where}.std", nullable=False)
            _validate_number(
                uncertainty, f"{row_where}.uncertainty", nullable=False
            )
            if std < 0:
                raise ValueError(f"{row_where}.std must be non-negative")
            if uncertainty < 0:
                raise ValueError(
                    f"{row_where}.uncertainty must be non-negative"
                )

    return reference, groups, scenarios, data


