def scale_delta(items) -> dict:
    """Compute per-scenario deltas between adjacent named stability scales.

    ``items`` must be a list of at least two mappings, each with exactly
    the keys ``name, result`` in that order.  ``name`` is a unique
    non-empty str and ``result`` is a complete :func:`stability_sum`
    result (schema ``climate-grid/ws-v1``); every member is validated
    against that contract.  Every result must share the same ``windows``,
    ``scenarios`` and ``items`` in the same order; ``windows`` and
    ``scenarios`` are taken from the first item.

    For every adjacent pair of items (in item order) and every scenario
    (in scenario order) a row is emitted: ``missing_delta`` is the later
    row's ``missing`` minus the earlier row's, ``level_deltas`` is the
    later row's ``levels`` minus the earlier row's elementwise (four
    ints), and only when both rows' ``rate`` and ``uncertainty`` are not
    ``None`` are ``rate_delta`` (later ``rate`` minus earlier ``rate``)
    and ``uncertainty`` (``hypot`` of the two uncertainties) computed;
    otherwise both are ``None``.

    The returned mapping uses the key order ``schema, scales, scenarios,
    data``; ``schema`` is ``climate-grid/wsd-v1``, ``scales`` lists the
    item names in item order and ``scenarios`` echoes the first item's
    result.  ``data`` follows the adjacent-pair-then-scenario order;
    each row uses the key order ``left, right, scenario, missing_delta,
    level_deltas, rate_delta, uncertainty`` with ``left``/``right`` the
    earlier/later item names.  Every output float is ``round(x, 12)``
    with negative zero normalized to ``0.0``.  The input is not
    modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least 2 items")

    names: list[str] = []
    validated: list[list] = []
    seen_names: set[str] = set()
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _STABILITY_SUM_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys name, result in order"
            )

        name = item["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate items name: {name!r}")
        seen_names.add(name)

        windows, scenarios, members, data = _validate_stability_sum(
            item["result"], where=f"{where}.result"
        )
        if not validated:
            first_windows = windows
            first_scenarios = scenarios
            first_members = members
        else:
            if windows != first_windows:
                raise ValueError(
                    "all items must share the same result windows in the "
                    "same order, taken from the first item"
                )
            if scenarios != first_scenarios:
                raise ValueError(
                    "all items must share the same result scenarios in the "
                    "same order, taken from the first item"
                )
            if members != first_members:
                raise ValueError(
                    "all items must share the same result items in the "
                    "same order, taken from the first item"
                )

        names.append(name)
        validated.append(data)

    rows = []
    for index in range(len(validated) - 1):
        left_data = validated[index]
        right_data = validated[index + 1]
        for s_index, scenario in enumerate(first_scenarios):
            left = left_data[s_index]
            right = right_data[s_index]
            missing_delta = _round_output(right["missing"] - left["missing"])
            level_deltas = [
                right_count - left_count
                for left_count, right_count in zip(
                    left["levels"], right["levels"]
                )
            ]
            if (
                left["rate"] is None
                or left["uncertainty"] is None
                or right["rate"] is None
                or right["uncertainty"] is None
            ):
                rate_delta = None
                uncertainty = None
            else:
                rate_delta = _round_output(right["rate"] - left["rate"])
                uncertainty = _round_output(
                    math.hypot(left["uncertainty"], right["uncertainty"])
                )
            rows.append(
                {
                    "left": names[index],
                    "right": names[index + 1],
                    "scenario": scenario,
                    "missing_delta": missing_delta,
                    "level_deltas": level_deltas,
                    "rate_delta": rate_delta,
                    "uncertainty": uncertainty,
                }
            )

    return {
        "schema": _SCALE_DELTA_SCHEMA,
        "scales": names,
        "scenarios": list(first_scenarios),
        "data": rows,
    }


def _validate_scale_delta(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list]:
    """Validate a complete :func:`scale_delta` result.

    Returns the scale names, the scenario order and the ``data`` rows.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _SCALE_SUMMARY_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, scales, "
            "scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _SCALE_DELTA_SCHEMA:
        raise ValueError(f"{where}.schema must be {_SCALE_DELTA_SCHEMA!r}")

    scales = _validate_string_list(
        result["scales"], f"{where}.scales", minimum=2
    )
    scenarios = _validate_string_list(result["scenarios"], f"{where}.scenarios")

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    expected = (len(scales) - 1) * len(scenarios)
    if len(data) != expected:
        raise ValueError(
            f"{where}.data must have {expected} rows (one per adjacent "
            "scale pair and scenario, in pair-then-scenario order)"
        )

    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _SCALE_SUMMARY_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys left, right, "
                "scenario, missing_delta, level_deltas, rate_delta, "
                "uncertainty in order"
            )

        pair_index, s_index = divmod(index, len(scenarios))

        left = row["left"]
        if not isinstance(left, str):
            raise TypeError(f"{row_where}.left must be a str")
        if left != scales[pair_index]:
            raise ValueError(
                f"{row_where}.left must be {scales[pair_index]!r} for its "
                "pair-then-scenario position"
            )

        right = row["right"]
        if not isinstance(right, str):
            raise TypeError(f"{row_where}.right must be a str")
        if right != scales[pair_index + 1]:
            raise ValueError(
                f"{row_where}.right must be {scales[pair_index + 1]!r} for "
                "its pair-then-scenario position"
            )

        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario != scenarios[s_index]:
            raise ValueError(
                f"{row_where}.scenario must be {scenarios[s_index]!r} for "
                "its pair-then-scenario position"
            )

        _validate_number(
            row["missing_delta"], f"{row_where}.missing_delta", nullable=False
        )
        if not -1 <= row["missing_delta"] <= 1:
            raise ValueError(
                f"{row_where}.missing_delta must be between -1 and 1"
            )

        level_deltas = row["level_deltas"]
        if not isinstance(level_deltas, list):
            raise TypeError(f"{row_where}.level_deltas must be a list")
        if len(level_deltas) != len(_STABILITY_LEVELS):
            raise ValueError(
                f"{row_where}.level_deltas must have "
                f"{len(_STABILITY_LEVELS)} deltas (stable, low, medium, high)"
            )
        for level_index, delta in enumerate(level_deltas):
            if not isinstance(delta, int) or isinstance(delta, bool):
                raise TypeError(
                    f"{row_where}.level_deltas[{level_index}] must be a "
                    "non-bool int"
                )

        rate_delta = row["rate_delta"]
        uncertainty = row["uncertainty"]
        if rate_delta is None or uncertainty is None:
            if rate_delta is not None or uncertainty is not None:
                raise ValueError(
                    f"{row_where}: rate_delta and uncertainty must be both "
                    "None or both present"
                )
            continue

        _validate_number(
            rate_delta, f"{row_where}.rate_delta", nullable=False
        )
        if not -1 <= rate_delta <= 1:
            raise ValueError(
                f"{row_where}.rate_delta must be between -1 and 1"
            )
        _validate_number(
            uncertainty, f"{row_where}.uncertainty", nullable=False
        )
        if uncertainty < 0:
            raise ValueError(f"{row_where}.uncertainty must be non-negative")

    return scales, scenarios, data


